// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CopyIcon, FileTextIcon } from 'lucide-react'

import {
  BrowserChrome,
  DemoStage,
  DockHeader,
  mockImage,
  type Build,
} from '@/app/demos/stage'
import { cn } from '@/shared/utils/cn'

import { ACTUAL, CAPTIONS, EXPECTED, PAGE, REPORT, STEPS_TEXT } from './script'

const build: Build = ({ tl, q, qa, step, final, move, click, type, wait, cursorOut }) => {
  step(0)
  tl.fromTo(
    q('page-meta'),
    { opacity: 0, y: -8 },
    { opacity: 1, y: 0, duration: 0.35, ease: 'back.out(2)' },
    0.3,
  )
  tl.fromTo(q('bug'), { opacity: 0, scale: 0.9 }, { opacity: 1, scale: 1, duration: 0.3 }, '<0.2')

  step(1, '+=0.5')
  move('expected', { ax: 0.2 })
  click('expected')
  type('expected-text', EXPECTED, { speed: 0.025 })
  move('actual', { ax: 0.2 })
  click('actual')
  type('actual-text', ACTUAL, { speed: 0.025 })

  step(2, '+=0.3')
  move('steps', { ax: 0.2, ay: 0.3 })
  click('steps')
  qa('steps-line').forEach((line, index) => type(line, STEPS_TEXT[index], { speed: 0.02 }))

  step(3, '+=0.3')
  move('generate')
  click('generate')
  tl.to(
    qa('field'),
    {
      rotateX: 75,
      y: (index) => -index * 18,
      opacity: 0,
      duration: 0.45,
      stagger: 0.05,
      ease: 'power3.in',
      transformOrigin: '50% 0%',
    },
    '<0.1',
  )
  tl.fromTo(
    q('report'),
    { opacity: 0, rotateX: -60, transformOrigin: '50% 0%' },
    { opacity: 1, rotateX: 0, duration: 0.5, ease: 'power3.out' },
    '-=0.1',
  )
  tl.fromTo(
    qa('report-line'),
    { opacity: 0 },
    { opacity: 1, duration: 0.15, stagger: 0.04 },
    '<0.15',
  )
  move('copy', { at: '+=0.2' })
  click('copy')
  tl.to(q('copy-text'), { text: 'Copied', duration: 0.01 }, '<')
  cursorOut('+=0.3')
  final()
  wait(1.4)
}

function Input({ d, label, lines }: { d: string; label: string; lines?: number }) {
  return (
    <div data-d="field">
      <p className="mb-0.5 text-[9.5px] font-medium text-ink-soft">{label}</p>
      <div
        data-d={d}
        className="rounded-lg border border-line bg-canvas/80 px-2 py-1 text-[9.5px] text-ink"
      >
        {lines ? (
          Array.from({ length: lines }, (_, index) => (
            <p key={index} data-d={`${d}-line`} className="h-[14px]" />
          ))
        ) : (
          <p data-d={`${d}-text`} className="h-[14px] truncate" />
        )}
      </div>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label="Bug Reporter filling a report for a layout bug and generating Markdown"
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome
        url={PAGE.url}
        panelWidth={258}
        panel={
          <div className="flex h-full flex-col">
            <DockHeader />
            <div className="relative flex min-h-0 flex-1 flex-col gap-1.5 p-2.5 [perspective:700px]">
              <div
                data-d="page-meta field"
                className="rounded-lg border border-line bg-ink/[0.04] px-2 py-1 text-[9px] opacity-0"
              >
                <p className="truncate font-medium text-ink">{PAGE.title}</p>
                <p className="truncate text-muted">{PAGE.url}</p>
              </div>
              <Input d="expected" label="Expected result" />
              <Input d="actual" label="Actual result" />
              <Input d="steps" label="Steps to reproduce" lines={3} />
              <div data-d="field">
                <span
                  data-d="generate"
                  className="flex h-7 w-fit items-center gap-1.5 rounded-lg bg-[var(--accent)] px-2.5 text-[10px] font-medium text-canvas"
                >
                  <FileTextIcon className="size-3" /> Generate report
                </span>
              </div>
              <div
                data-d="report"
                className="absolute inset-2.5 flex flex-col rounded-lg border border-line-strong bg-canvas opacity-0"
              >
                <div className="flex items-center justify-between border-b border-line px-2 py-1">
                  <span className="text-[9.5px] font-medium text-ink">Bug report</span>
                  <span data-d="copy" className="flex items-center gap-1 text-[9px] text-muted">
                    <CopyIcon className="size-2.5" /> <span data-d="copy-text">Copy</span>
                  </span>
                </div>
                <div className="space-y-px overflow-hidden px-2 py-1.5 font-mono text-[8.5px] leading-[13px]">
                  {REPORT.map((line, index) => (
                    <p
                      key={index}
                      data-d="report-line"
                      className={cn(
                        'truncate',
                        line.startsWith('#') ? 'mt-1 text-[var(--accent)]' : 'text-ink-soft',
                      )}
                    >
                      {line}
                    </p>
                  ))}
                </div>
              </div>
            </div>
          </div>
        }
      >
        <div className="h-full bg-[#fafafa] px-3 pt-3 text-[#111]">
          <h3 className="text-[14px] font-bold tracking-tight">New arrivals</h3>
          <div className="mt-2 grid grid-cols-2 gap-2">
            {['Aero Lamp', 'Glass Vase', 'Oak Desk', 'Clay Mug'].map((name, index) => (
              <div key={name} className="relative rounded-lg bg-white p-1.5 shadow-sm">
                <div className="h-12 rounded-md" style={{ background: mockImage(index + 1) }} />
                <p className="mt-1 text-[8.5px] font-medium">{name}</p>
                <p
                  className={cn(
                    'text-[8.5px] text-[#7c3aed]',
                    index === 1 && 'absolute left-4 top-5 rounded bg-white px-1',
                  )}
                >
                  ${[89, 36, 410, 18][index]}
                </p>
                {index === 1 ? (
                  <span
                    data-d="bug"
                    className="absolute -inset-1 rounded-xl border-2 border-dashed border-[#ef4444] opacity-0"
                  />
                ) : null}
              </div>
            ))}
          </div>
        </div>
      </BrowserChrome>
    </DemoStage>
  )
}
